{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the objective to maximize total profit (revenue from sales minus cost of purchases), or literally total revenue from sales only?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive objective functions, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a limit on how many units can be purchased in any given month, or can you buy any quantity at the listed monthly purchase price?"
  ],
  "rationale": "The response asks a single clarification question regarding purchase quantity limits, presented as a binary choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you sell units in a given month, must those units have been in stock at the start of that month (i.e., you cannot sell units you purchase in the same month), or can purchases and sales in the same month be matched freely?"
  ],
  "rationale": "The response asks for a single policy choice regarding the timing of inventory availability for sales, which constitutes one semantically independent question."
}

