  ],
  "rationale": "The response asks a single clarification question regarding the constraints on sales volume relative to starting inventory."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the warehouse capacity of 500 units a limit on the inventory at the end of each month (after that month's purchases and sales), or on the inventory at the start of each month?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the timing of the capacity constraint, presenting two mutually exclusive options for one specific rule."
}

{
  "action": "question",
